def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty")

    # Select a solution with high potential for improvement (prioritize those with higher combined values)
    selected_idx = np.random.choice(len(archive), p=np.array([v1 + v2 for _, (v1, v2) in archive]) / sum(v1 + v2 for _, (v1, v2) in archive))
    base_solution = archive[selected_idx][0].copy()
    new_solution = base_solution.copy()
    current_weight = np.sum(weight_lst * new_solution)

    # Probabilistic item selection for flipping
    included_items = np.where(new_solution == 1)[0]
    excluded_items = np.where(new_solution == 0)[0]

    if len(included_items) > 0 and len(excluded_items) > 0:
        # Value-weighted probabilities for flipping
        flip_candidates = np.concatenate([included_items, excluded_items])
        flip_probs = np.zeros(len(flip_candidates))
        for i, idx in enumerate(flip_candidates):
            if new_solution[idx] == 1:
                flip_probs[i] = (value1_lst[idx] + value2_lst[idx]) * 0.5  # Prefer removing high-value items
            else:
                flip_probs[i] = (value1_lst[idx] + value2_lst[idx]) * 1.5  # Prefer adding high-value items
        flip_probs = flip_probs / np.sum(flip_probs)

        # Perform probabilistic flips
        for _ in range(min(3, len(flip_candidates))):
            flip_idx = np.random.choice(flip_candidates, p=flip_probs)
            if new_solution[flip_idx] == 1:
                if current_weight - weight_lst[flip_idx] <= capacity:
                    new_solution[flip_idx] = 0
                    current_weight -= weight_lst[flip_idx]
            else:
                if current_weight + weight_lst[flip_idx] <= capacity:
                    new_solution[flip_idx] = 1
                    current_weight += weight_lst[flip_idx]

    # Guided neighborhood exploration: flip items based on marginal improvement
    if np.array_equal(new_solution, base_solution):
        marginal_values = np.zeros(len(weight_lst))
        for i in range(len(weight_lst)):
            if new_solution[i] == 1:
                marginal_values[i] = (value1_lst[i] + value2_lst[i]) * 0.5
            else:
                marginal_values[i] = (value1_lst[i] + value2_lst[i]) * 1.5
        marginal_values = marginal_values / np.sum(marginal_values)

        for _ in range(min(5, len(weight_lst))):
            flip_idx = np.random.choice(len(weight_lst), p=marginal_values)
            if new_solution[flip_idx] == 1:
                if current_weight - weight_lst[flip_idx] <= capacity:
                    new_solution[flip_idx] = 0
                    current_weight -= weight_lst[flip_idx]
            else:
                if current_weight + weight_lst[flip_idx] <= capacity:
                    new_solution[flip_idx] = 1
                    current_weight += weight_lst[flip_idx]

    return new_solution

